mapper.select:
SELECT s.* FROM s_session_slot s
JOIN s_venue v ON v.id = s.venue_id AND v.status = 'ACTIVE'
JOIN s_court c ON c.id = s.court_id AND c.status = 'ACTIVE'
JOIN s_court_sport cs ON cs.court_id = c.id AND cs.sport_type_id = s.sport_type_id
JOIN s_sport_type st ON st.id = s.sport_type_id AND st.status = 'ACTIVE'
WHERE s.venue_id = #{venueId}
  AND s.sport_type_id = #{sportTypeId}
  AND s.slot_date = #{date}
  AND s.status = 'OPEN'
  AND s.start_at > DATE_ADD(UTC_TIMESTAMP(3), INTERVAL v.min_booking_minutes MINUTE)
  AND s.slot_date BETWEEN DATE(CONVERT_TZ(UTC_TIMESTAMP(3), '+00:00', '+08:00'))
      AND DATE_ADD(DATE(CONVERT_TZ(UTC_TIMESTAMP(3), '+00:00', '+08:00')),
          INTERVAL (v.booking_days_ahead - 1) DAY)
  AND TIME(CONVERT_TZ(s.start_at, '+00:00', '+08:00')) >= #{startTime}
  AND TIME(CONVERT_TZ(s.end_at, '+00:00', '+08:00')) <= #{endTime}
ORDER BY s.start_at, s.id

SELECT * FROM s_session_slot
WHERE weekly_slot_id = #{weeklySlotId} AND template_slot_date = #{date}
ORDER BY id LIMIT 1 FOR UPDATE

mapper.update:
UPDATE s_session_slot
SET status = #{slot.status}, hold_booking_id = NULL, hold_expires_at = NULL,
    updated_at = #{slot.updatedAt}
WHERE id = #{slot.id}

mapper.select:
SELECT COUNT(*)
FROM s_session_slot
WHERE weekly_slot_id = #{weeklySlotId}
  AND template_slot_date = #{templateSlotDate}
  AND manual_override = 1

SELECT COUNT(*)
FROM s_session_slot
WHERE court_id = #{courtId}
  AND status IN ('OPEN', 'HELD', 'BOOKED')
  AND start_at < #{endAt}
  AND end_at > #{startAt}

  AND (weekly_slot_id IS NULL OR weekly_slot_id != #{weeklySlotId})

FOR UPDATE

SELECT COUNT(*)
FROM s_session_slot
WHERE court_id = #{courtId}
  AND id != #{excludedSlotId}
  AND status IN ('OPEN', 'HELD', 'BOOKED')
  AND start_at < #{endAt}
  AND end_at > #{startAt}
FOR UPDATE

