UPDATE s_session_slot
SET status = 'CLOSED', updated_at = UTC_TIMESTAMP(3)
WHERE weekly_slot_id = #{weeklySlotId}
  AND status = 'OPEN'
  AND start_at >= #{now}
  AND manual_override = 0

